public class DivisionAnalyzer {
    public static void examineDivisions() {
        // Floating-point division: adheres to IEEE 754
        double floatResult = 1.0 / 0.0;
        System.out.println("1.0 / 0.0 = " + floatResult); // Prints: Infinity

        // Integer division: violates integer math rules, triggers exception
        try {
            int intResult = 1 / 0;
        } catch (ArithmeticException e) {
            System.out.println("Caught expected: " + e.getMessage()); // Prints: / by zero
        }
    }
}
